function main(inputs) {
  const sort_by = inputs.sort_by ?? 'created_at';
  const sort_order = inputs.sort_order ?? 'desc';
  if (!['created_at', 'last_used_at'].includes(sort_by)) throw new Error('不支持的排序字段');
  if (!['asc', 'desc'].includes(sort_order)) throw new Error('不支持的排序方向');
  const catalog = inputs.results[0].rows[0][0];
  const direction = sort_order === 'asc' ? 1 : -1;
  catalog.items.sort((a, b) => {
    const av = a[sort_by], bv = b[sort_by];
    if (av == null && bv != null) return 1;
    if (bv == null && av != null) return -1;
    const delta = av == null ? 0 : Date.parse(av) - Date.parse(bv);
    if (delta) return direction * delta;
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
  });
  return { catalog };
}
